WITH "m0" AS ( UPDATE "public"."mutation_item" AS "s" SET "title" = $1 WHERE ( true AND ( "s"."id" = $2 ) ) RETURNING "s" AS "t0" , NULL::tid AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) FROM "r0" AS "t0" )
WITH "m0" AS ( DELETE FROM "public"."mutation_item" AS "s" WHERE ( true AND ( "s"."id" = $1 ) ) RETURNING "s" AS "t0" , "s"."ctid" AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) FROM "r0" AS "t0" )
